package mockvalidator
import("crypto/rand";"crypto/rsa";"crypto/tls";"crypto/x509";"crypto/x509/pkix";"encoding/pem";"fmt";"math/big";"net";"sync";"time";"github.com/pion/dtls/v2";"custom-router/internal/protocol")
// Config controls the fake Validator.
type Config struct{Organization string;AuthorizedSerials map[string]bool;Endpoints []protocol.ControllerEndpoint;RejectSignature bool}
// Server is a runnable DTLS Validator for lab tests.
type Server struct{Config Config;Listener net.Listener;RootPEM []byte;Connections,ClosedConnections int;mu sync.Mutex;done chan struct{}}
// New starts a fake Validator on a random local UDP port.
func New(c Config)(*Server,error){if c.Organization==""{c.Organization="NLS-LAB"};if c.AuthorizedSerials==nil{c.AuthorizedSerials=map[string]bool{}};if len(c.Endpoints)==0{c.Endpoints=[]protocol.ControllerEndpoint{{Role:"controller",Address:"http://127.0.0.1:18080"},{Role:"manager",Address:"http://127.0.0.1:18081"}}};rk,e:=rsa.GenerateKey(rand.Reader,2048);if e!=nil{return nil,fmt.Errorf("root key: %w",e)};root,e:=makeCert("NLS-LAB Root CA",c.Organization,rk,nil,nil,true);if e!=nil{return nil,e};sk,e:=rsa.GenerateKey(rand.Reader,2048);if e!=nil{return nil,fmt.Errorf("server key: %w",e)};srv,e:=makeCert("validator",c.Organization,sk,root,rk,false);if e!=nil{return nil,e};l,e:=dtls.Listen("udp",&net.UDPAddr{IP:net.IPv4(127,0,0,1),Port:0},&dtls.Config{Certificates:[]tls.Certificate{{Certificate:[][]byte{srv.Raw},PrivateKey:sk}}});if e!=nil{return nil,fmt.Errorf("listen DTLS: %w",e)};s:=&Server{Config:c,Listener:l,RootPEM:pem.EncodeToMemory(&pem.Block{Type:"CERTIFICATE",Bytes:root.Raw}),done:make(chan struct{})};go s.accept();return s,nil}
func(s *Server)accept(){for{c,e:=s.Listener.Accept();if e!=nil{select{case<-s.done:return;default:continue}};s.mu.Lock();s.Connections++;s.mu.Unlock();go s.handle(c)}}
func(s *Server)handle(c net.Conn){defer func(){c.Close();s.mu.Lock();s.ClosedConnections++;s.mu.Unlock()}();c.SetDeadline(time.Now().Add(5*time.Second));nonce:=make([]byte,32);if _,e:=rand.Read(nonce);e!=nil{return};if e:=protocol.Write(c,protocol.MsgChallenge,protocol.Challenge{Nonce:nonce});e!=nil{return};var r protocol.ChallengeResponse;t,e:=protocol.NewCodec(c).Read(&r);if e!=nil||t!=protocol.MsgChallengeResponse{return};if !s.Config.AuthorizedSerials[r.Serial]{protocol.Write(c,protocol.MsgError,protocol.ErrorMessage{Code:"UNKNOWN_SERIAL",Detail:r.Serial});return};if s.Config.RejectSignature{protocol.Write(c,protocol.MsgError,protocol.ErrorMessage{Code:"BAD_SIGNATURE",Detail:"forced"});return};bl,_:=pem.Decode(r.BoardIDCertificate);if bl==nil{return};if e=protocol.VerifyChallengeSignature(bl.Bytes,nonce,r.Signature);e!=nil{protocol.Write(c,protocol.MsgError,protocol.ErrorMessage{Code:"BAD_SIGNATURE",Detail:e.Error()});return};protocol.Write(c,protocol.MsgControllerList,protocol.ControllerList{Endpoints:s.Config.Endpoints})}
// Addr returns the Validator address.
func(s *Server)Addr()string{return s.Listener.Addr().String()}
// Close stops the fake Validator.
func(s *Server)Close()error{select{case<-s.done:default:close(s.done)};return s.Listener.Close()}
func makeCert(cn,org string,key *rsa.PrivateKey,parent *x509.Certificate,parentKey *rsa.PrivateKey,isCA bool)(*x509.Certificate,error){sn,_:=rand.Int(rand.Reader,new(big.Int).Lsh(big.NewInt(1),120));now:=time.Now();t:=&x509.Certificate{SerialNumber:sn,Subject:pkix.Name{CommonName:cn,Organization:[]string{org}},NotBefore:now.Add(-time.Minute),NotAfter:now.Add(time.Hour),KeyUsage:x509.KeyUsageDigitalSignature|x509.KeyUsageKeyEncipherment,ExtKeyUsage:[]x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth}};if isCA{t.IsCA=true;t.BasicConstraintsValid=true;t.KeyUsage|=x509.KeyUsageCertSign};signer:=key;pc:=t;if parent!=nil{signer=parentKey;pc=parent};der,e:=x509.CreateCertificate(rand.Reader,t,pc,&key.PublicKey,signer);if e!=nil{return nil,fmt.Errorf("create cert: %w",e)};return x509.ParseCertificate(der)}
